"use strict";
const $=selector=>document.querySelector(selector);
const state={view:"organize",configured:false,busy:false,operation:null,data:{total:0,topic_counts:{},mistakes:[]},topic:"",chats:{organize:[],review:[],analysis:[]},traces:{organize:[],review:[],analysis:[]},notices:{},artifacts:new Map()};
const intake={queue:[],imageIds:[],submitted:null,saved:new Set(),collapsed:false,cursor:{start:0,end:0}};
const titles={organize:["添加学习内容","添加学习内容","上传或粘贴原稿，笔记与错题可以放在一起。"],notebook:["我的错题本","我的错题本","查看题目、原答案和错因，选择内容进一步分析。"],notes:["我的笔记","我的笔记","直接阅读笔记与公式，下载和删除都在对应条目中。"],review:["复习练习","复习练习","从资料与错题中选题，按知识点或细分标签练习。"],materials:["练习资料","练习资料","批量导入 PDF 或图片，核对后整理成题库。"],analysis:["问 AI","问 AI","围绕所选内容提问；左侧建议只填入问题，由你确认发送。"]};
const toolNames={search_notes:"检索笔记",save_mistake:"保存错题",get_mistakes:"读取历史错题",pick_exercise:"从资料中选题",save_note:"保存笔记",delete_records:"生成待确认删除清单",merge_records:"生成合并预览"};
/* 历史对话状态：organize 的草稿/消息/收藏按对话隔离；其他视图仍用全局 state。 */
const conversationStore={list:[],activeId:null,cache:new Map(),available:false,restoring:false,draftTimer:null,switchSeq:0,switchChain:Promise.resolve()};
function conversationCache(id){if(!id)return null;let entry=conversationStore.cache.get(id);if(!entry){entry={id,messages:[],traces:[],artifacts:new Map(),draft:"",imageIds:[],queue:[],follow:"",pageRange:"",collapsed:false,cursor:{start:0,end:0},submitted:null,saved:new Set(),busy:false,operation:null,restoredImages:0,finished:false,loaded:false,notice:null,saveChain:Promise.resolve()};conversationStore.cache.set(id,entry);}return entry;}
function activeConversation(){return conversationCache(conversationStore.activeId);}
// organize 的忙碌只看当前对话；历史对话 API 不可用时退回旧的全局 busy 语义。
function isActiveConversationBusy(){if(!conversationStore.available)return state.busy;const entry=activeConversation();return Boolean(entry&&entry.busy)||Boolean(state.busy&&state.operation?.view!=="organize");}
function syncConversationBusy(){if(!conversationStore.available)return;const entry=activeConversation();const foreign=Boolean(state.busy&&state.operation&&state.operation.view!=="organize");if(!foreign){if(entry&&entry.operation){state.operation=entry.operation;state.busy=true;}else if(!state.operation||state.operation.view==="organize"){state.operation=null;state.busy=false;}}updateButtons();}
// 标记某个对话 busy/operation；当前对话的 operation 同时同步到全局（停止按钮、操作条）。
function setConversationBusy(id,value,operation){const entry=conversationCache(id);if(!entry)return;entry.busy=Boolean(value);if(value)entry.operation=operation||entry.operation;else entry.operation=null;const summary=conversationStore.list.find(item=>item.id===id);if(summary)summary.busy=Boolean(value);if(id===conversationStore.activeId){const foreign=Boolean(state.busy&&state.operation&&state.operation.view!=="organize");if(!foreign){if(value){state.operation=entry.operation;state.busy=true;}else if(!state.operation||state.operation===operation||state.operation.view==="organize"){state.operation=null;state.busy=false;}}}updateButtons();renderConversationList();}
function updateConversationSummary(id,patch){const summary=conversationStore.list.find(item=>item.id===id);if(summary)Object.assign(summary,patch);renderConversationList();}
// 发起请求时先乐观更新列表标题（服务端在请求开始时把「新对话」改成可见文字前 18 字；前端不等完成）。
function optimisticConversationTitle(id,text){if(!id)return "";const summary=conversationStore.list.find(item=>item.id===id);if(!summary)return "";const current=String(summary.title||"").trim();if(current&&current!=="新对话")return current;const title=String(text||"").replace(/[\r\n]+/g," ").replace(/\s+/g," ").trim().slice(0,18);if(title)summary.title=title;return summary.title;}
async function patchConversationIntake(id,text,version){if(!conversationStore.available||!id)return;const entry=conversationCache(id);const value=String(text||"");const run=async()=>{try{await api(`/api/conversations/${encodeURIComponent(id)}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({intake_text:value})});const cached=readCachedDraft(id);if(cached&&cached.text===value&&(version==null||cached.version===Number(version)))clearCachedDraft(id);}catch(error){/* 草稿保存失败不阻塞切换；未落盘内容由 sessionStorage 兜底 */}};entry.saveChain=(entry.saveChain||Promise.resolve()).then(run,run);return entry.saveChain;}
function scheduleDraftSave(){if(!conversationStore.available||conversationStore.restoring)return;const id=conversationStore.activeId;if(!id)return;const value=$("#draft").value;const entry=conversationCache(id);const version=(entry.draftVersion||0)+1;entry.draftVersion=version;entry.draft=value;cacheDraft(id,value,version);if(conversationStore.draftTimer)clearTimeout(conversationStore.draftTimer);conversationStore.draftTimer=setTimeout(()=>{conversationStore.draftTimer=null;void patchConversationIntake(id,value,version);},900);}
function cancelDraftSave(){if(conversationStore.draftTimer){clearTimeout(conversationStore.draftTimer);conversationStore.draftTimer=null;}}
function conversationTime(value){try{const date=new Date(value||"");if(Number.isNaN(date.getTime()))return "";const now=new Date();if(date.toDateString()===now.toDateString())return date.toLocaleTimeString("zh-CN",{hour:"2-digit",minute:"2-digit"});return date.toLocaleDateString("zh-CN",{month:"2-digit",day:"2-digit"});}catch(error){return "";}}
function stashConversationWorkspace(){const entry=activeConversation();if(!entry)return;entry.draft=$("#draft").value;entry.queue=intake.queue.slice();entry.imageIds=[...intake.imageIds];entry.submitted=intake.submitted;entry.saved=intake.saved;entry.collapsed=intake.collapsed;entry.cursor={...intake.cursor};entry.follow=$("#organize-follow").value;entry.pageRange=$("#input-page-range").value;entry.messages=state.chats.organize;entry.traces=state.traces.organize;entry.artifacts=state.artifacts;}
function renderOrganizeChat(){if(!state.chats.organize.length){const container=$("#organize-messages");container.replaceChildren();const empty=make("div","empty-chat");empty.append(make("h3","","先把内容交给我"),make("p","","笔记保留原有顺序，错题逐步引导。信息不清楚时，在这里补充就好。"));container.append(empty);$("#organize-follow-form").hidden=true;return;}renderChat("organize");}
// 把某对话的存档写到工作区（草稿/图片/消息/收藏），供切换与刷新恢复。
function applyConversationWorkspace(entry){conversationStore.restoring=true;try{intake.queue=[...(entry.queue||[])];intake.imageIds=[...(entry.imageIds||[])];intake.submitted=entry.submitted??null;intake.saved=entry.saved instanceof Set?entry.saved:new Set(entry.saved||[]);entry.saved=intake.saved;intake.collapsed=Boolean(entry.collapsed);intake.cursor=entry.cursor?{...entry.cursor}:{start:0,end:0};state.chats.organize=entry.messages;state.traces.organize=entry.traces;state.artifacts=entry.artifacts;$("#draft").value=entry.draft||"";$("#organize-follow").value=entry.follow||"";$("#organize-follow-form").hidden=true;$("#input-page-range").value=entry.pageRange||"";$("#organize-suggestions").hidden=true;$("#organize-messages").replaceChildren();if(entry.notice){state.notices.organize=entry.notice;entry.notice=null;}else delete state.notices.organize;renderNotice();renderOrganizeChat();renderFileQueue();updateDraft();updateIntake();renderArtifacts();renderTrace("organize");if(typeof renderChatQueues==="function")renderChatQueues();syncMathEditorToConversation(entry.id||null);}finally{conversationStore.restoring=false;}}
// 工作区已经换成目标对话之后才同步公式编辑器：装载这份草稿，并把撤回/重做历史重置成该对话的基线。
// syncConversation 按稳定对话 id 去重，所以同一对话内（含原文/渲染视图互切）的撤回重做继续有效，
// 换到另一个对话才重置，A 对话的原稿绝不会在 B 对话里被撤回。同步期间 async MathLive input 由编辑器忽略。
function syncMathEditorToConversation(id){if(!window.mathInputMode||typeof window.mathInputMode.syncConversation!=="function")return;try{window.mathInputMode.syncConversation(id);}catch(error){/* 公式编辑器未就绪时不影响历史对话 */}}
const DRAFT_CACHE_PREFIX="study-history-draft:";
function cacheDraft(id,text,version){if(!id)return;try{sessionStorage.setItem(DRAFT_CACHE_PREFIX+id,JSON.stringify({text:String(text==null?"":text),version:Number(version)||0}));}catch(error){/* sessionStorage 不可用时忽略 */}}
function readCachedDraft(id){if(!id)return null;try{const raw=sessionStorage.getItem(DRAFT_CACHE_PREFIX+id);if(!raw)return null;const data=JSON.parse(raw);if(!data||typeof data.text!=="string")return null;return {text:data.text,version:Number(data.version)||0};}catch(error){return null;}}
function clearCachedDraft(id){if(!id)return;try{sessionStorage.removeItem(DRAFT_CACHE_PREFIX+id);}catch(error){/* 忽略 */}}
function isConversationCurrent(id){return !conversationStore.available||!id||id===conversationStore.activeId;}
function conversationNotice(id,text,error=false){if(!text)return;if(conversationStore.available&&id&&id!==conversationStore.activeId){const entry=conversationCache(id);if(entry)entry.notice={text,error:Boolean(error)};return;}notify(text,error,"organize");}
function nextConversationSwitch(){conversationStore.switchSeq+=1;return conversationStore.switchSeq;}
function conversationSwitchCurrent(seq){return seq===conversationStore.switchSeq;}
function insertDraftText(value,selection,text){const source=String(value==null?"":value);const start=Math.min(Math.max(selection?.start??0,0),source.length);const end=Math.min(Math.max(selection?.end??start,start),source.length);if(source.length-(end-start)+String(text||"").length>80000)throw new Error("插入后超过 80000 字，原有文字保留，请分批整理。");return source.slice(0,start)+text+source.slice(end);}

function make(tag,className,text){const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;}
function notify(text,error=false,view=state.operation?.view||state.view){state.notices[view]={text,error};renderNotice();}
function renderNotice(){const info=state.notices[state.view]||{};const node=$("#notice");node.textContent=info.text||"";node.hidden=!info.text;node.classList.toggle("error",Boolean(info.error));}
async function api(path,options={}){let response;try{response=await fetch(path,options);}catch(error){throw new Error("无法连接本机服务，请确认网页服务仍在运行。原有输入保留，可修改后重试。");}let data;try{data=await response.json();}catch(error){throw new Error("服务返回的内容无法读取，请稍后重试。");}if(!response.ok||!data.ok){const error=new Error(data.error||"操作未完成。");error.events=data.events;error.cancelled=Boolean(data.cancelled);error.contextRetained=Boolean(data.context_retained);error.status=response.status;throw error;}return data;}
let richSerial=0;
function richNonce(){richSerial+=1;return richSerial.toString(36).toUpperCase()+Math.random().toString(36).slice(2,8).toUpperCase();}
function richInlineMath(source,next){if(!source||source.includes("\n"))return false;if(/^\s|\s$/.test(source))return false;if(next&&/[0-9]/.test(next))return false;return true;}
function richFind(text,start,closer,limit){const stop=limit===undefined?text.length:Math.min(text.length,limit);for(let i=start;i<stop;i+=1){if(text.startsWith(closer,i))return i;if(text[i]==="\\")i+=1;}return -1;}
function richEnvironment(name){return /^(?:aligned|align\*?|equation\*?|cases|pmatrix|bmatrix|vmatrix|array|matrix|gathered)$/.test(name);}
function richMathValue(source,display,raw){let tex=source;if(display&&/^\\begin\{/.test(tex))tex=tex.replace(/\\(begin|end)\{align\*?\}/g,"\\$1{aligned}").replace(/\\(?:begin|end)\{equation\*?\}/g,"");return {tex:tex,raw:raw||source};}
function richStripQuote(source,text,start){return /(?:^|\n)[ \t]*>[ \t]*$/.test(text.slice(0,start))?source.replace(/\n[ \t]*>[ \t]?/g,"\n"):source;}
function richProtect(text,parts,mathPrefix,tokenEnd){
 let out="",i=0;
 const math=(source,display,raw,start)=>{source=richStripQuote(source,text,start);const value=richMathValue(source,display,raw);parts.push({tex:value.tex,raw:value.raw,display:display});return mathPrefix+(parts.length-1)+tokenEnd;};
 while(i<text.length){
  if(text.startsWith("~~~",i)&&(i===0||text[i-1]==="\n")){const end=text.indexOf("~~~",i+3);const stop=end<0?text.length:end+3;out+=text.slice(i,stop);i=stop;continue;}
  if(text.startsWith("```",i)){const end=text.indexOf("```",i+3);const stop=end<0?text.length:end+3;out+=text.slice(i,stop);i=stop;continue;}
  if(text[i]==="`"){let n=1;while(text[i+n]==="`")n+=1;const fence="`".repeat(n);const end=text.indexOf(fence,i+n);const stop=end<0?text.length:end+n;out+=text.slice(i,stop);i=stop;continue;}
  if((i===0||text[i-1]==="\n")&&((text[i]===" "&&text[i+1]===" "&&text[i+2]===" "&&text[i+3]===" ")||text[i]==="\t")){const end=text.indexOf("\n",i);const stop=end<0?text.length:end;out+=text.slice(i,stop);i=stop;continue;}
  if(text[i]==="<"&&/^<(pre|code)\b/i.test(text.slice(i,i+8))){const match=/^<(pre|code)\b/i.exec(text.slice(i,i+8));const tag=match[1].toLowerCase();const end=text.toLowerCase().indexOf("</"+tag+">",i);const stop=end<0?text.length:end+tag.length+3;out+=text.slice(i,stop);i=stop;continue;}
  if(text[i]==="<"){const close=text.indexOf(">",i+1);if(close>=0){const candidate=text.slice(i,close+1);if(/^<\/?[A-Za-z][^>\n]*>$/.test(candidate)){out+=candidate;i=close+1;continue;}}}
  if(text.startsWith("\\$",i)){out+="$";i+=2;continue;}
  if(text.startsWith("\\[",i)){const end=richFind(text,i+2,"\\]");if(end>=0){out+=math(text.slice(i+2,end),true,text.slice(i,end+2),i);i=end+2;continue;}}
  if(text.startsWith("\\(",i)){const end=richFind(text,i+2,"\\)");if(end>=0){out+=math(text.slice(i+2,end),false,text.slice(i,end+2),i);i=end+2;continue;}}
  if(text.startsWith("$$",i)){const end=richFind(text,i+2,"$$");if(end>=0){out+=math(text.slice(i+2,end),true,text.slice(i,end+2),i);i=end+2;continue;}out+="$$";i+=2;continue;}
  if(text[i]==="$"){const lineEnd=text.indexOf("\n",i+1);const end=richFind(text,i+1,"$",lineEnd<0?undefined:lineEnd);if(end>=0&&richInlineMath(text.slice(i+1,end),text[end+1])){out+=math(text.slice(i+1,end),false,text.slice(i,end+1),i);i=end+1;continue;}out+="$";i+=1;continue;}
  if(text.startsWith("\\begin{",i)){const env=/^\\begin\{([A-Za-z*]+)\}/.exec(text.slice(i));if(env&&richEnvironment(env[1])){const close="\\end{"+env[1]+"}";const end=text.indexOf(close,i);if(end>=0){const stop=end+close.length;out+=math(text.slice(i,stop),true,text.slice(i,stop),i);i=stop;continue;}}}
  out+=text[i];i+=1;
 }
 return out;
}
function richInsideCode(node){let current=node.parentNode;while(current&&current.nodeType===1){const name=current.nodeName.toLowerCase();if(name==="code"||name==="pre")return true;current=current.parentNode;}return false;}
function richMathNode(part){
 const wrapper=document.createElement("span");
 wrapper.className=part.display?"math-display":"math-inline";
 wrapper.setAttribute("style",part.display?"display:block;max-width:100%;overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch":"display:inline-block;max-width:100%;overflow-x:auto;overflow-y:hidden;vertical-align:middle");
 try{if(window.katex&&typeof window.katex.render==="function")window.katex.render(part.tex,wrapper,{displayMode:part.display,throwOnError:false,trust:false,strict:"ignore"});else wrapper.textContent=part.raw;}catch(error){wrapper.textContent=part.raw;}
 return wrapper;
}
function richPattern(mathPrefix,tokenEnd){return new RegExp(mathPrefix+"(\\d+)"+tokenEnd,"g");}
function richRestoreAttributes(element,parts,mathPrefix,tokenEnd){
 const pattern=richPattern(mathPrefix,tokenEnd);
 for(const child of element.querySelectorAll("*")){for(const attr of Array.from(child.attributes||[])){pattern.lastIndex=0;if(!pattern.test(attr.value))continue;pattern.lastIndex=0;child.setAttribute(attr.name,attr.value.replace(pattern,(token,index)=>{const part=parts[Number(index)];return part?part.raw:token;}));}}
}
function richRestore(element,parts,mathPrefix,tokenEnd){
 if(!element||!parts.length)return;
 const pattern=richPattern(mathPrefix,tokenEnd);
 const walker=document.createTreeWalker(element,4,null);const nodes=[];while(walker.nextNode()){const node=walker.currentNode;if(!richInsideCode(node))nodes.push(node);}
 for(const node of nodes){
  const text=node.nodeValue||"";pattern.lastIndex=0;if(!pattern.test(text))continue;pattern.lastIndex=0;
  const fragment=document.createDocumentFragment();let last=0,match;
  while((match=pattern.exec(text))){if(match.index>last)fragment.appendChild(document.createTextNode(text.slice(last,match.index)));const part=parts[Number(match[1])];if(!part){fragment.appendChild(document.createTextNode(match[0]));}else{fragment.appendChild(richMathNode(part));}last=pattern.lastIndex;}
  if(last<text.length)fragment.appendChild(document.createTextNode(text.slice(last)));
  if(node.parentNode)node.parentNode.replaceChild(fragment,node);
 }
}
function rich(element,value){
 let text=String(value||"").replace(/^\s*```(?:markdown|md)\s*\n([\s\S]*?)\n```\s*$/i,"$1");
 text=text.replace(/```(?:math|latex|tex)\s*\n([\s\S]*?)\n```/gi,(_,math)=>"\n$$\n"+math+"\n$$\n");
 const nonce=richNonce(),mathPrefix="STUDYMATH"+nonce+"M",tokenEnd="Z",parts=[];
 const protectedText=richProtect(text,parts,mathPrefix,tokenEnd);
 if(window.marked&&window.DOMPurify){
  const options={FORBID_TAGS:["img","iframe","object","script","style"]};
  const dirty=DOMPurify.sanitize(marked.parse(protectedText,{breaks:true}),options);
  element.innerHTML=dirty;
  richRestoreAttributes(element,parts,mathPrefix,tokenEnd);
  element.innerHTML=DOMPurify.sanitize(element.innerHTML,options);
  element.querySelectorAll("a").forEach(a=>{a.target="_blank";a.rel="noopener noreferrer";});
  richRestore(element,parts,mathPrefix,tokenEnd);
 }else element.textContent=text;
}
function showView(view){if(!titles[view])view="organize";state.view=view;if(view==="analysis"&&typeof ensureAnalysisContext==="function")ensureAnalysisContext();document.querySelectorAll(".view").forEach(node=>node.hidden=node.id!==`view-${view}`);document.querySelectorAll(".nav-item").forEach(button=>{button.classList.toggle("active",button.dataset.view===view);button.setAttribute("aria-current",button.dataset.view===view?"page":"false");});$("#view-context").textContent=titles[view][0];$("#page-title").textContent=titles[view][1];$("#page-subtitle").textContent=titles[view][2];if(location.hash!==`#${view}`)history.replaceState(null,"",`#${view}`);$("#clear-intake").hidden=!["organize","materials"].includes(view);renderNotice();if(view==="review"&&typeof loadReviewCatalog==="function")void loadReviewCatalog();if(view==="materials"&&typeof renderMaterials==="function")renderMaterials();if(typeof updateSelectionTray==="function")updateSelectionTray();if(view==="notebook")renderNotebook();if(view==="notes")renderNotes();if(typeof updateReviewLayout==="function")updateReviewLayout();if(typeof renderChatQueues==="function")renderChatQueues();}
function updateButtons(){const organizeBusy=isActiveConversationBusy();const submitted=intake.submitted!==null&&$("#draft").value.trim()===intake.submitted;$("#organize-submit").disabled=organizeBusy||!state.configured||(!$("#draft").value.trim()&&!intake.queue.length&&!intake.imageIds.length)||submitted;$("#organize-submit span").textContent=submitted?"已提交，可在对话中补充":"交给 AI 整理";$("#draft").readOnly=organizeBusy;$("#recognize-button").disabled=organizeBusy||!intake.queue.some(item=>!item.read);$("#recognize-button").hidden=!intake.queue.some(item=>!item.read);$("#input-page-range").parentElement.hidden=!intake.queue.some(item=>!item.read&&/\.pdf$/i.test(item.file.name));$("#image-pane>.helper").hidden=!intake.queue.length;for(const id of ["image-input","new-mistake","toggle-source","clear-intake"]){$("#"+id).disabled=organizeBusy;}
 if(typeof updateReviewButtons==="function")updateReviewButtons();$("#save-settings").disabled=state.busy;$("#stop-request").hidden=!state.busy;document.querySelectorAll("#stop-request,[data-stop-request]").forEach(button=>{button.disabled=Boolean(state.operation?.stopping);button.textContent=state.operation?.stopping?"正在停止…":"停止并编辑";});
 $("#ocr-operation").hidden=!(state.busy&&state.operation?.type==="intake-read");$("#materials-operation").hidden=!(state.busy&&state.operation?.type?.startsWith("materials-")&&state.operation.type!=="materials-read");for(const view of ["organize","review","analysis"]){$(`#${view}-operation`).hidden=!(state.busy&&state.operation?.type==="chat"&&state.operation.view===view);$(`#${view}-follow`).readOnly=state.busy&&state.operation?.type!=="chat";}
 document.querySelectorAll(".follow-form button").forEach(button=>button.disabled=state.busy||!state.configured);if(typeof updateMaterialButtons==="function")updateMaterialButtons();if(typeof updateLibraryButtons==="function")updateLibraryButtons();if(typeof updateChatComposerButtons==="function")updateChatComposerButtons();}
function setBusy(value){state.busy=value;updateButtons();if(typeof updateChatComposerButtons==="function")updateChatComposerButtons();document.querySelectorAll("[data-ocr-backend]").forEach(node=>{node.disabled=value||Boolean(state.ocrChoicePending);});if(typeof watchLocalOcrProgress==="function")watchLocalOcrProgress(value);}
function updateDraft(){const editor=$("#draft");intake.cursor={start:editor.selectionStart,end:editor.selectionEnd};$("#draft-count").textContent=`${editor.value.length} / 80000`;scheduleDraftSave();updateButtons();/* 公式可视化模式：把外部写入（填入示例 / OCR / 清空）同步进公式编辑器 */if(window.mathInputMode)window.mathInputMode.onExternalChange();}
function updateIntake(){const saved=intake.saved.size>0;$("#source-summary").hidden=!saved;$("#source-summary-title").textContent=`本次已收录 ${intake.saved.size} 条内容`;$("#source-panel").hidden=intake.collapsed;$("#organize-workspace").classList.toggle("source-collapsed",intake.collapsed);$("#toggle-source").textContent=intake.collapsed?"查看原稿":"收起原稿";const restored=Number(activeConversation()?.restoredImages||0);const hint=$("#intake-restored-hint");if(hint){const show=restored>0&&!intake.queue.length;hint.textContent=show?`本对话已有 ${restored} 张原稿图（来自上次上传），继续发送会作为文字补充的原图。`:"";hint.hidden=!show;}}
function focusDraftEditor(){if(window.mathInputMode&&typeof window.mathInputMode.focusVisible==="function"){window.mathInputMode.focusVisible();return;}const editor=$("#draft");editor.focus();try{editor.setSelectionRange(intake.cursor.start,intake.cursor.end);}catch(error){}}
function selectSource(source){document.querySelectorAll("[data-source]").forEach(button=>{button.classList.toggle("active",button.dataset.source===source);button.setAttribute("aria-pressed",String(button.dataset.source===source));});$("#image-pane").hidden=source==="text";if(source==="text")focusDraftEditor();}
function addFiles(files){if(isActiveConversationBusy())return;for(const file of files){if(!/\.(pdf|txt|md|jpe?g|png|webp)$/i.test(file.name)){notify("支持 PDF、TXT、Markdown、JPG、PNG 和 WebP。",true,"organize");continue;}const limit=/\.pdf$/i.test(file.name)?256:8;if(file.size>limit*1024*1024){notify(`${file.name} 超过 ${limit} MB。`,true,"organize");continue;}if(intake.queue.length>=20){notify("每批最多选择 20 个文件。",true,"organize");break;}if(!intake.queue.some(item=>item.file.name===file.name&&item.file.size===file.size&&item.file.lastModified===file.lastModified))intake.queue.push({file,read:false});}$("#image-input").value="";renderFileQueue();}
function renderFileQueue(){const list=$("#input-files");const organizeBusy=isActiveConversationBusy();list.replaceChildren();intake.queue.forEach(item=>{const row=make("div","queued-file");row.append(make("span","",item.file.name),make("small","",item.read?"已读取":"待读取"));const remove=make("button","text-button","移除");remove.type="button";remove.hidden=item.read;remove.disabled=organizeBusy;remove.addEventListener("click",()=>{intake.queue=intake.queue.filter(other=>other!==item);renderFileQueue();});const preview=make("button","text-button","预览");preview.type="button";preview.disabled=organizeBusy;preview.dataset.filePreview="";preview.addEventListener("click",()=>openFilePreview(item.file,"#input-page-range"));row.append(preview,remove);list.append(row);});updateButtons();}
function insertRecognizedText(text,selection){const editor=$("#draft");const start=Math.min(selection.start,editor.value.length),end=Math.min(selection.end,editor.value.length);if(editor.value.length-(end-start)+text.length>80000)throw new Error("插入后超过 80000 字，原有文字保留，请分批整理。");editor.setRangeText(text,start,end,"end");updateDraft();}
async function recognize(){if(isActiveConversationBusy())return;const conversationId=conversationStore.available?conversationStore.activeId:null;const queue=intake.queue.filter(item=>!item.read);if(!queue.length)return;if(queue.reduce((sum,item)=>sum+item.file.size,0)>512*1024*1024){notify("每批文件合计不能超过 512 MB。",true);return;}const operation={id:crypto.randomUUID(),type:"intake-read",view:"organize",conversationId,selection:{...intake.cursor},stopping:false};beginOrganizeOperation(operation);if(isConversationCurrent(conversationId))notify("");try{const pageRange=$("#input-page-range").value;const imageIds=[...intake.imageIds];const form=new FormData();for(const item of queue)form.append("files",item.file);form.append("page_range",pageRange);form.append("keep_image_ids",JSON.stringify(imageIds));form.append("request_id",operation.id);if(conversationId)form.append("conversation_id",conversationId);const result=await api("/api/intake/read",{method:"POST",body:form});const entry=conversationId?conversationCache(conversationId):null;const current=isConversationCurrent(conversationId);if(entry){entry.imageIds=[...result.image_ids];entry.restoredImages=entry.imageIds.length;}if(current){intake.imageIds=result.image_ids;insertRecognizedText(result.text,operation.selection);}else if(entry){entry.draft=insertDraftText(entry.draft||"",operation.selection,result.text);entry.draftVersion=(entry.draftVersion||0)+1;cacheDraft(conversationId,entry.draft,entry.draftVersion);void patchConversationIntake(conversationId,entry.draft,entry.draftVersion);conversationNotice(conversationId,`已读取 ${result.pages.length} 页 / 份，文字已存入该对话，切换后可见。`);}queue.forEach(item=>item.read=true);if(current){renderFileQueue();updateIntake();notify(`已读取 ${result.pages.length} 页 / 份，文字可修改。`);focusDraftEditor();}}catch(error){conversationNotice(conversationId,error.cancelled?"已停止读取，原有文字保留。":error.message,!error.cancelled);}finally{endOrganizeOperation(operation);}}
function renderChat(view){const container=$(`#${view}-messages`);if(!state.chats[view].length)return;container.replaceChildren();for(const item of state.chats[view]){if(view==="review"&&item.selectionRequest)continue;const card=make("article",`message ${item.role}`);card.append(make("div","message-label",item.role==="user"?"你":item.role==="error"?"未完成":item.role==="notice"?"已停止":"学习助手"));const body=make("div","message-body");rich(body,view==="review"&&item.selectedQuestionId&&item.selectedQuestionId===reviewState.question?.id?"先试一小步：你会从哪里入手？写出第一步，我再帮你检查。":item.text);if(item.images?.length)renderChatImages(body,item.images);card.append(body);container.append(card);}$(`#${view}-follow-form`).hidden=false;container.scrollTop=container.scrollHeight;}
function renderTrace(view){const node=$(`#${view}-trace`);node.hidden=!state.traces[view].length;const content=node.querySelector(".trace-content");content.replaceChildren();for(const item of state.traces[view]){const row=make("div","trace-event");row.append(make("strong","",item.event==="工具请求"?toolNames[item.value.name]||item.value.name:item.event));row.append(make("pre","",JSON.stringify(item.value,null,2)));content.append(row);}}
function applySaveResults(events,conversationId){const entry=conversationId?conversationCache(conversationId):null;const savedSet=entry?entry.saved:intake.saved;const artifacts=entry?entry.artifacts:state.artifacts;let name=null;for(const event of events||[]){if(event.event==="工具请求")name=event.value.name;if(event.event!=="工具结果")continue;const result=event.value;if(result.ok&&name==="save_note"&&result.data?.note){const note=result.data.note;savedSet.add(`note:${note.id}`);artifacts.set(`note:${note.id}`,{kind:"note",record:note,downloads:Object.fromEntries(Object.entries(result.data.exports||{}).filter(([,value])=>value.ok).map(([kind])=>[kind,`/api/notes/${note.id}/download/${kind}`]))});}if(result.ok&&name==="save_mistake"&&result.data?.mistake){const record=result.data.mistake;savedSet.add(`mistake:${record.id}`);artifacts.set(`mistake:${record.id}`,{kind:"mistake",record});}name=null;}if(entry&&entry!==activeConversation())return;if(savedSet.size)intake.collapsed=true;updateIntake();renderArtifacts();}
function renderArtifacts(){const container=$("#organize-results");container.replaceChildren();if(!state.artifacts.size)return;container.append(make("h2","","本次已保存内容"));for(const item of state.artifacts.values())container.append(makeRecordCard(item.kind,item.record,{downloads:item.downloads,inline:true}));}
async function sendMessage(text,view,editTarget=`${view}-follow`,editorText=text,requestOptions={}){const isOrganize=view==="organize";const requestedConversationId=requestOptions.conversationId;const conversationId=isOrganize&&conversationStore.available?(requestedConversationId||conversationStore.activeId):null;const targetEntry=isOrganize&&conversationId?conversationCache(conversationId):null;if(isOrganize){if(!text.trim())return false;if(state.busy&&state.operation&&state.operation.view!=="organize")return false;if(conversationStore.available&&(!targetEntry||targetEntry.busy))return false;}else if(state.busy||!text.trim())return false;if(view==="analysis")ensureAnalysisContext();if(!state.configured){notify("请先在右上角保存模型设置。",true,view);return false;}const {attachments=[],displayText,conversationId:ignoredConversationId,...chatOptions}=requestOptions;const operation={id:crypto.randomUUID(),type:"chat",view,editTarget,editorText,stopping:false,message:text,attachments,chatOptions,conversationId,outcome:"pending",historyRetained:false,chatStarted:false};const messages=targetEntry?targetEntry.messages:state.chats[view];const activeNow=()=>!isOrganize||!conversationStore.available||conversationId===conversationStore.activeId;if(isOrganize){if(activeNow())state.chats[view]=messages;if(conversationId)setConversationBusy(conversationId,true,operation);else{state.operation=operation;setBusy(true);}}else{state.operation=operation;setBusy(true);}messages.push({role:"user",text:displayText??(editTarget==="draft"?editorText:text),images:attachments.map(item=>({url:item.url,name:item.file.name,file:item.file}))});if(isOrganize&&conversationId){optimisticConversationTitle(conversationId,displayText??text);const summary=conversationStore.list.find(item=>item.id===conversationId);if(summary)summary.message_count=Number(summary.message_count||0)+1;renderConversationList();}if(activeNow()){renderChat(view);notify("","organize");}try{const attachedIds=attachments.length?await prepareChatAttachments(attachments,operation):[];if(operation.stopping){const error=new Error("已停止，可编辑后重新发送。");error.cancelled=true;throw error;}operation.chatStarted=true;const result=await api("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:text,request_id:operation.id,view,scope:"current",...(isOrganize&&displayText?{display_text:displayText}:{}),...chatOptions,...(conversationId?{conversation_id:conversationId}:{}),...(attachedIds.length?{image_ids:attachedIds}:{})})});operation.outcome="success";messages.push({role:"assistant",text:result.answer});if(view==="review"&&result.current_question)setReviewQuestion(result.current_question);if(attachments.length)completeChatAttachments(attachments);if(isOrganize){if(targetEntry){targetEntry.traces=result.events||[];if(activeNow())state.traces.organize=targetEntry.traces;applySaveResults(result.events,conversationId);updateConversationSummary(conversationId,{message_count:messages.length,updated_at:new Date().toISOString()});}else state.traces.organize=result.events||[];}else state.traces[view]=result.events||[];if(result.proposals?.length&&activeNow())showProposals(result.proposals);}catch(error){operation.outcome=error.cancelled?"cancelled":"error";operation.historyRetained=error.contextRetained;operation.failure=error;if(operation.steering){messages.push({role:"notice",text:"已接收补充，正在继续当前任务。"});}else{if(attachments.length&&activeNow())composerFeedback(view,error.message,!error.cancelled);messages.push({role:error.cancelled?"notice":"error",text:error.message});}if(isOrganize){if(targetEntry){targetEntry.traces=error.events||[];if(activeNow())state.traces.organize=targetEntry.traces;applySaveResults(error.events,conversationId);}else state.traces.organize=error.events||[];if(activeNow()){if(!intake.saved.size&&!operation.steering)intake.submitted=null;if(error.cancelled&&!operation.steering)intake.collapsed=false;updateIntake();}}else state.traces[view]=error.events||[];if(!operation.steering){const restored=typeof retainFailedChat==="function"&&retainFailedChat(operation);if(activeNow()){const editor=document.getElementById(editTarget);if(editor&&!restored){if(!editor.value.trim())editor.value=editorText;editor.focus();}notify(error.message,!error.cancelled,view);}}}finally{if(isOrganize){if(conversationId)setConversationBusy(conversationId,false,operation);if(targetEntry)targetEntry.finished=true;if(activeNow()){const foreign=Boolean(state.busy&&state.operation&&state.operation.view!=="organize");if(!foreign){if(!state.operation||state.operation===operation||state.operation.view==="organize")state.operation=null;state.busy=false;}renderChat("organize");renderTrace("organize");const suggest=state.chats.organize.at(-1)?.role==="assistant";$("#organize-suggestions").hidden=!suggest;}await Promise.allSettled([loadMistakes(),loadNotes()]);renderConversationList();void refreshConversations();}else{if(state.operation===operation)state.operation=null;setBusy(false);if(typeof syncConversationBusy==="function")syncConversationBusy();renderChat(view);renderTrace(view);await Promise.allSettled([loadMistakes(),loadNotes()]);const suggest=!state.busy&&state.chats.organize.at(-1)?.role==="assistant";$("#organize-suggestions").hidden=!suggest;}if(typeof chatRequestFinished==="function")chatRequestFinished(operation);}return true;}
async function loadMistakes(){try{const result=await api("/api/mistakes");state.data=result.data;$("#sidebar-count").textContent=result.data.total;if(typeof loadReviewCatalog==="function")void loadReviewCatalog();renderNotebook();updateButtons();}catch(error){notify(error.message,true,"notebook");}}
function resetIntake(clearMessages=true,conversationId=conversationStore.available?conversationStore.activeId:null){const entry=conversationId?conversationCache(conversationId):null;const active=!conversationStore.available||!conversationId||conversationId===conversationStore.activeId;if(typeof clearQueuedChat==="function")clearQueuedChat("organize",conversationId??undefined);if(entry){entry.draft="";entry.queue=[];entry.imageIds=[];entry.submitted=null;entry.saved=new Set();entry.artifacts=new Map();entry.restoredImages=0;entry.collapsed=false;entry.cursor={start:0,end:0};entry.follow="";entry.pageRange="";if(clearMessages){entry.messages=[];entry.traces=[];}}if(active){intake.queue=[];intake.imageIds=[];intake.submitted=null;intake.saved=entry?entry.saved:new Set();intake.collapsed=false;intake.cursor={start:0,end:0};state.artifacts=entry?entry.artifacts:new Map();if(clearMessages){state.chats.organize=entry?entry.messages:[];state.traces.organize=entry?entry.traces:[];}$("#organize-suggestions").hidden=true;$("#draft").value="";$("#input-page-range").value="";$("#organize-follow").value="";$("#organize-follow-form").hidden=true;if(clearMessages){$("#organize-messages").replaceChildren();renderOrganizeChat();}renderFileQueue();updateDraft();updateIntake();renderArtifacts();renderTrace("organize");}if(conversationId){clearCachedDraft(conversationId);void patchConversationIntake(conversationId,"");}}
async function refreshStatus(){const result=await api("/api/status");state.configured=result.configured;state.localOcr=Boolean(result.local_ocr);if(typeof syncOcrChoice==="function")syncOcrChoice(result);if(typeof syncChatModels==="function")syncChatModels(result.model);$("#material-source-model").textContent=result.local_ocr?"本机 GLM-OCR 读取原图 → 文字模型整理题目与答案；识别不消耗 API 额度。":"原图整理使用："+(result.ocr_model||"图片模型")+"。可在模型设置中更换。";document.querySelectorAll("[data-local-ocr-info]").forEach(node=>{node.textContent=result.local_ocr?"已启用 GLM 本机识别，两个上传入口共用；首次加载后逐页处理，约占 1.7 GB 内存，空闲一分钟自动释放。整理与讲解仍使用已配置的文字模型。":"已选择云端识图，使用模型设置中的图片服务，产生 API 费用；可随时切回本机 GLM。";});$("#model-status").replaceChildren(make("span","status-dot"),make("span","",result.configured?`已配置 · ${result.model||"模型"}`:"待配置模型"));$("#config-banner").hidden=result.configured;if(result.version!=="workspace-v20")notify("检测到旧版网页服务。请先关闭旧启动窗口，再双击 start_web.cmd 重启；只刷新页面不会加载新的后端。",true);updateButtons();return result;}
async function stopRequest(){if(typeof pauseChatQueue==="function")pauseChatQueue();const operation=state.view==="organize"&&conversationStore.available?(activeConversation()?.operation||state.operation):state.operation;if(!operation||operation.stopping)return;operation.stopping=true;updateButtons();try{await api("/api/cancel",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({request_id:operation.id})});}catch(error){operation.stopping=false;updateButtons();notify(error.message,true);}}
function hasTextSelection(){const element=document.activeElement;return typeof element?.selectionStart==="number"&&element.selectionStart!==element.selectionEnd||Boolean(window.getSelection()?.toString());}
async function clearIntake(ask=true){if(isActiveConversationBusy())return;if(ask&&!confirm("清除本对话的上传文件、原稿文字和本轮模型上下文吗？历史消息、已收录的笔记 / 错题 / 练习资料，以及其他对话都会保留。"))return;const conversationId=conversationStore.available?conversationStore.activeId:null;const entry=conversationId?conversationCache(conversationId):null;const files=intake.queue.map(item=>item.file),ids=files.map(file=>filePreview.cache.get(file)?.id).filter(Boolean);const operation={id:crypto.randomUUID(),type:"intake-clear",view:"organize",conversationId,stopping:false};beginOrganizeOperation(operation);cancelDraftSave();try{if(entry)await entry.saveChain;await api("/api/intake/clear",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({preview_ids:ids,...(conversationId?{conversation_id:conversationId}:{})})});for(const file of files){filePreview.cache.delete(file);if(filePreview.file===file){if($("#file-preview-dialog").open)$("#file-preview-dialog").close();closeFilePreview();filePreview.file=null;filePreview.document=null;}}const current=isConversationCurrent(conversationId);if(current){resetIntake(false,conversationId);selectSource("image");notify("本对话的原稿与临时文件已清除，本轮模型上下文已重置；历史消息与已收录内容保留。",false,"organize");focusDraftEditor();}else if(entry){entry.draft="";entry.queue=[];entry.imageIds=[];entry.submitted=null;entry.saved=new Set();entry.artifacts=new Map();entry.restoredImages=0;entry.collapsed=false;entry.cursor={start:0,end:0};entry.follow="";entry.pageRange="";clearCachedDraft(conversationId);if(typeof clearQueuedChat==="function")clearQueuedChat("organize",conversationId);conversationNotice(conversationId,"本对话的原稿与临时文件已清除，历史消息保留。");renderConversationList();}}catch(error){conversationNotice(conversationId,error.message,true);}finally{endOrganizeOperation(operation);}}
async function refreshConversations(){if(!conversationStore.available)return;const result=await api("/api/conversations");conversationStore.list=result.conversations||[];const known=conversationStore.list.some(item=>item.id===conversationStore.activeId);if(!known){const next=conversationStore.list.some(item=>item.id===result.active)?result.active:(conversationStore.list[0]?.id||null);if(next)void openConversation(next,{silent:true});}renderConversationList();}
async function loadConversations(){try{const result=await api("/api/conversations");conversationStore.available=true;conversationStore.list=result.conversations||[];conversationStore.activeId=result.active||conversationStore.list[0]?.id||null;if(!conversationStore.list.length){const created=await api("/api/conversations",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});conversationStore.activeId=created.active;conversationStore.list=[created.conversation];}renderConversationList();return true;}catch(error){conversationStore.available=false;renderConversationList();return false;}}
// 切换对话：保存旧对话草稿 → activate → 拉详情 → 覆盖本地工作区；旧对话在飞请求不 abort，完成后按 id 回写。
async function openConversation(id,options={}){if(!id||!conversationStore.available)return;return enqueueConversationSwitch(()=>openConversationNow(id,options));}
function enqueueConversationSwitch(task){const run=conversationStore.switchChain.then(task,task);conversationStore.switchChain=run.catch(()=>{});return run;}
async function openConversationNow(id,options={}){const seq=nextConversationSwitch();const silent=Boolean(options.silent);const previous=conversationStore.activeId;cancelDraftSave();if(previous&&previous!==id){stashConversationWorkspace();const previousEntry=conversationCache(previous);const clearing=previousEntry?.operation?.type==="intake-clear";if(!clearing)await patchConversationIntake(previous,$("#draft").value,conversationCache(previous).draftVersion);if(!conversationSwitchCurrent(seq))return;}try{const detail=await api(`/api/conversations/${encodeURIComponent(id)}`);if(!conversationSwitchCurrent(seq))return;await api(`/api/conversations/${encodeURIComponent(id)}/activate`,{method:"POST"});if(!conversationSwitchCurrent(seq))return;conversationStore.activeId=id;const entry=conversationCache(id);const server=detail.conversation||{};const serverMessages=(server.messages||[]).map(message=>({role:message.role,text:message.text}));if(!entry.loaded){const cached=readCachedDraft(id);entry.messages=serverMessages;entry.draft=cached?cached.text:(server.intake?.text??"");entry.draftVersion=cached?cached.version:0;entry.imageIds=[...(server.intake?.image_ids||[])];entry.restoredImages=Number(server.intake?.image_count||0);}else{if(serverMessages.length>entry.messages.length)entry.messages=serverMessages;entry.restoredImages=Math.max(Number(entry.restoredImages||0),Number(server.intake?.image_count||0));}entry.loaded=true;applyConversationWorkspace(entry);renderConversationList();syncConversationBusy();updateButtons();if(!silent)$("#draft").focus();}catch(error){if(conversationSwitchCurrent(seq))conversationNotice(id,error.message,true);}}
async function createConversationOnServer(){return api("/api/conversations",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});}
// 新对话：只清空本地工作区与服务器草稿，不动其他对话的消息。
function newConversation(){if(!conversationStore.available)return Promise.resolve();return enqueueConversationSwitch(newConversationNow);}
async function newConversationNow(){const seq=nextConversationSwitch();const previous=conversationStore.activeId;cancelDraftSave();if(previous){stashConversationWorkspace();const previousEntry=conversationCache(previous);if(previousEntry?.operation?.type!=="intake-clear")await patchConversationIntake(previous,$("#draft").value,previousEntry.draftVersion);if(!conversationSwitchCurrent(seq))return;}try{const result=await createConversationOnServer();if(!conversationSwitchCurrent(seq))return;conversationStore.activeId=result.active;conversationStore.list=[result.conversation,...conversationStore.list.filter(item=>item.id!==result.active)];const entry=conversationCache(result.active);entry.messages=[];entry.traces=[];entry.artifacts=new Map();entry.saved=new Set();entry.queue=[];entry.draft="";entry.imageIds=[];entry.submitted=null;entry.collapsed=false;entry.cursor={start:0,end:0};entry.follow="";entry.pageRange="";entry.restoredImages=0;entry.finished=false;entry.loaded=true;applyConversationWorkspace(entry);renderConversationList();syncConversationBusy();updateButtons();$("#draft").value="";updateDraft();$("#draft").focus();notify(`已新建对话：${result.conversation?.title||"新对话"}`,false,"organize");}catch(error){if(conversationSwitchCurrent(seq))notify(error.message,true,"organize");}}
function deleteConversation(id){if(!conversationStore.available)return Promise.resolve();const entry=conversationCache(id);if(entry&&entry.busy){notify("处理中，不能删除",true,"organize");return Promise.resolve();}if(!confirm("删除这个对话吗？对话里的消息会一并删除。"))return Promise.resolve();return enqueueConversationSwitch(()=>deleteConversationNow(id));}
async function deleteConversationNow(id){try{const result=await api(`/api/conversations/${encodeURIComponent(id)}`,{method:"DELETE"});conversationStore.cache.delete(id);clearCachedDraft(id);if(typeof clearQueuedChat==="function")clearQueuedChat("organize",id);conversationStore.list=conversationStore.list.filter(item=>item.id!==id);const deletedActive=conversationStore.activeId===id;renderConversationList();if(deletedActive){const next=result.active||conversationStore.list[0]?.id||null;if(next){conversationStore.activeId=next;await openConversationNow(next,{silent:true});}else conversationStore.activeId=null;}notify("已删除对话。",false,"organize");}catch(error){notify(error.status===409?"处理中，不能删除":error.message,true,"organize");}}
function renderConversationList(){const list=$("#conversation-list");if(!list)return;list.replaceChildren();if(!conversationStore.available){list.append(make("li","conversation-empty","历史对话不可用（本机服务未提供会话接口）"));return;}const items=conversationStore.list||[];if(!items.length){list.append(make("li","conversation-empty","还没有对话"));return;}for(const summary of items){const entry=conversationCache(summary.id);const busy=Boolean(entry?.busy||summary.busy);const item=make("li",`conversation-item${summary.id===conversationStore.activeId?" active":""}`);item.dataset.conversationId=summary.id;const open=make("button","conversation-open");open.type="button";open.setAttribute("aria-label",`打开对话：${summary.title||"新对话"}`);const title=make("span","conversation-title",summary.title||"新对话");const meta=make("span","conversation-meta");if(busy){meta.append(make("span","conversation-spinner"),make("span","","处理中"),make("span","",`${summary.message_count??entry?.messages.length??0} 条消息`));}else{if(entry?.finished)meta.append(make("span","conversation-finished","已完成"));meta.append(make("span","",`${summary.message_count??entry?.messages.length??0} 条消息`),make("span","",conversationTime(summary.updated_at||summary.created_at)));}open.append(title,meta);open.addEventListener("click",()=>{if(summary.id!==conversationStore.activeId)void openConversation(summary.id);});const remove=make("button","conversation-delete","×");remove.type="button";remove.title="删除对话";remove.setAttribute("aria-label",`删除对话：${summary.title||"新对话"}`);remove.disabled=busy;remove.addEventListener("click",event=>{event.stopPropagation();void deleteConversation(summary.id);});item.append(open,remove);list.append(item);}}
// organize 的 intake/chat 操作按对话标记忙碌，前台操作同步到全局（停止按钮/操作条）。
function beginOrganizeOperation(operation){if(conversationStore.available&&operation.conversationId){setConversationBusy(operation.conversationId,true,operation);}else{state.operation=operation;setBusy(true);}}
function endOrganizeOperation(operation){if(conversationStore.available&&operation.conversationId){setConversationBusy(operation.conversationId,false,operation);}else{if(state.operation===operation)state.operation=null;setBusy(false);}}
async function init(){try{for(const key of ["study-agent-draft","study-material-draft","study-material-source"])localStorage.removeItem(key);}catch(error){}for(const id of ["draft","organize-follow","review-follow","analysis-follow","image-input"])$("#"+id).value="";
 document.querySelectorAll(".nav-item").forEach(button=>button.addEventListener("click",()=>showView(button.dataset.view)));document.querySelectorAll("[data-source]").forEach(button=>button.addEventListener("click",()=>selectSource(button.dataset.source)));window.addEventListener("hashchange",()=>showView(location.hash.slice(1)));
 for(const event of ["input","select","click","keyup","blur"])$("#draft").addEventListener(event,updateDraft);$("#image-input").addEventListener("change",event=>addFiles(event.target.files));for(const type of ["dragenter","dragover"])$("#drop-zone").addEventListener(type,event=>{event.preventDefault();$("#drop-zone").classList.add("dragging");});for(const type of ["dragleave","drop"])$("#drop-zone").addEventListener(type,event=>{event.preventDefault();$("#drop-zone").classList.remove("dragging");if(type==="drop")addFiles(event.dataTransfer.files);});$("#drop-zone").addEventListener("keydown",event=>{if(["Enter"," "].includes(event.key)){event.preventDefault();$("#image-input").click();}});
 $("#recognize-button").addEventListener("click",recognize);$("#organize-submit").addEventListener("click",submitOriginalIntake);$("#new-conversation").addEventListener("click",()=>void newConversation());/* 符号键盘面板展开时会挤压原稿面板：鼠标按住按钮期间面板收起会造成布局位移，click 可能落空。用 pointerdown 的落点兜底提交，避免"按钮亮着却点了没反应"。 */let organizeSubmitPressed=false;document.addEventListener("pointerdown",event=>{organizeSubmitPressed=Boolean(event.target instanceof Element&&event.target.closest&&event.target.closest("#organize-submit"));},true);document.addEventListener("click",event=>{if(!organizeSubmitPressed)return;organizeSubmitPressed=false;if(event.target instanceof Element&&event.target.closest&&event.target.closest("#organize-submit"))return;if($("#organize-submit").disabled)return;window.setTimeout(()=>{void submitOriginalIntake();},0);},true);
 $("#toggle-source").addEventListener("click",()=>{intake.collapsed=!intake.collapsed;updateIntake();});$("#new-mistake").addEventListener("click",()=>{if(isActiveConversationBusy())return;if($("#draft").value.trim()!==intake.submitted&&$("#draft").value.trim()&&!confirm("原稿有未提交的修改，清空并添加下一份吗？"))return;clearIntake(false);});
 for(const view of ["organize","review","analysis"]){$(`#${view}-follow-form`).addEventListener("submit",event=>{event.preventDefault();submitChatFollowup(view);});}
 $("#practice-current").addEventListener("click",()=>sendMessage("从我的资料中选一道与当前题同知识点的原题，先不给答案。","organize","organize-follow","",{intent:"practice"}));
 $("#clear-intake").addEventListener("click",()=>state.view==="materials"?clearMaterialDraft():clearIntake());document.querySelectorAll("#stop-request,[data-stop-request]").forEach(button=>button.addEventListener("click",stopRequest));document.addEventListener("keydown",event=>{if(event.isComposing||document.querySelector("dialog[open]"))return;if(state.busy&&(event.key==="Escape"||(event.ctrlKey&&event.key.toLowerCase()==="c"&&!hasTextSelection()))){event.preventDefault();stopRequest();}else if(event.altKey&&event.key==="Enter"&&event.target.matches(".follow-form > textarea")){event.preventDefault();steerDraft(event.target.id.replace("-follow",""));}else if((event.ctrlKey||event.metaKey)&&event.key==="Enter"&&event.target.matches(".follow-form > textarea")){event.preventDefault();event.target.form.requestSubmit();}});
 updateDraft();updateIntake();showView(location.hash.slice(1)||"organize");try{await refreshStatus();}catch(error){notify(error.message,true);}try{const conversationsReady=await loadConversations();if(conversationsReady&&conversationStore.activeId)await openConversation(conversationStore.activeId,{silent:true});}catch(error){/* 历史对话不可用时不阻塞原有流程 */}window.addEventListener("pagehide",()=>{if(!conversationStore.available)return;try{if(window.mathInputMode&&typeof window.mathInputMode.flush==="function")window.mathInputMode.flush();}catch(error){}const id=conversationStore.activeId;if(!id)return;const entry=conversationCache(id);if(entry&&entry.operation?.type==="intake-clear")return;cancelDraftSave();const value=$("#draft").value;if(entry){entry.draft=value;cacheDraft(id,value,entry.draftVersion);}try{fetch(`/api/conversations/${encodeURIComponent(id)}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({intake_text:value}),keepalive:true}).catch(()=>{});}catch(error){/* 关闭页面时尽力保存草稿 */}});await Promise.allSettled([loadMistakes(),loadNotes()]);}
window.addEventListener("DOMContentLoaded",init);
